-- Table "procedure" in schema "cds2db_in"
-------------------------------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS cds2db_in.procedure (
    procedure_id int PRIMARY KEY DEFAULT nextval('db.db_seq') -- Primary key of the entity
);

DO $$
BEGIN
    IF EXISTS ( -- Table exists
        SELECT
            1
        FROM (
            SELECT
                1 s
            FROM
                information_schema.columns
            WHERE
                table_schema = 'cds2db_in'
                AND table_name = 'procedure') a,
            (
                SELECT
                    1 s
                FROM
                    db_config.db_parameter
                WHERE
                    parameter_name = 'current_migration_flag'
                    AND parameter_value = '1') b
            WHERE
                a.s = b.s) THEN
        IF NOT EXISTS ( -- column not exists
            SELECT
                1
            FROM
                information_schema.columns
            WHERE
                table_schema = 'cds2db_in'
                AND table_name = 'procedure'
                AND column_name = 'input_datetime') THEN
        ALTER TABLE cds2db_in.procedure
            ADD procedure_raw_id int NOT NULL;
    -- Primary key of the corresponding raw table
    NULL;
END IF;
    -- column
    -- Organizational items - fixed for each database table -----------------------------------------
    IF NOT EXISTS ( -- column not exists
        SELECT
            1
        FROM
            information_schema.columns
        WHERE
            table_schema = 'cds2db_in'
            AND table_name = 'procedure'
            AND column_name = 'input_datetime') THEN
        ALTER TABLE cds2db_in.procedure
            ADD input_datetime timestamp NOT NULL DEFAULT CURRENT_TIMESTAMP;
    -- Time at which data record was created
END IF;
    -- column
    IF NOT EXISTS ( -- column not exists
        SELECT
            1
        FROM
            information_schema.columns
        WHERE
            table_schema = 'cds2db_in'
            AND table_name = 'procedure'
            AND column_name = 'last_check_datetime') THEN
        ALTER TABLE cds2db_in.procedure
            ADD last_check_datetime timestamp DEFAULT NULL;
    -- Time at which data record was last checked
END IF;
    -- column
    IF NOT EXISTS ( -- column not exists
        SELECT
            1
        FROM
            information_schema.columns
        WHERE
            table_schema = 'cds2db_in'
            AND table_name = 'procedure'
            AND column_name = 'current_dataset_status') THEN
        ALTER TABLE cds2db_in.procedure
            ADD current_dataset_status varchar DEFAULT 'input';
    -- Processing status of the data record
END IF;
    -- column
    IF NOT EXISTS ( -- column not exists
        SELECT
            1
        FROM
