DO $$
BEGIN
    IF EXISTS ( -- do migration
        SELECT
            1
        FROM
            db_config.db_parameter
        WHERE
            parameter_name = 'current_migration_flag'
            AND parameter_value = '1') THEN
        ------------------------------------------------------------------------------------------------
        ------------------------- Index for cds2db_in - encounter ---------------------------------
        -- Primary key of the corresponding raw table
        IF EXISTS ( -- target column
            SELECT
                1
            FROM
                information_schema.columns
            WHERE
                table_schema = 'cds2db_in'
                AND table_name = 'encounter'
                AND column_name = 'encounter_id') THEN
            IF EXISTS ( -- INDEX available
                SELECT
                    1
                FROM
                    pg_indexes
                WHERE
                    substr(indexname, 1, 63) = substr('idx_encounter_raw_id', 1, 63)
                    AND schemaname = 'cds2db_in'
                    AND tablename = 'encounter') THEN
                -- check current status
                IF EXISTS ( -- INDEX nicht auf akuellen Stand
                    SELECT
                        1
                    FROM
                        pg_indexes
                    WHERE
                        schemaname NOT IN ('pg_catalog', 'information_schema')
                        AND schemaname = 'cds2db_in'
                        AND tablename = 'encounter'
                        AND substr(indexname, 1, 63) = substr('idx_encounter_raw_id', 1, 63)
